// Optimization: Memoization / Dynamic Programming
// Avoids redundant re-calculation of subproblems (e.g., O(2^N) -> O(N))

static long long lookup[100] = {0};

long long fib_opt(int n) {
    if (n <= 1) return n;

    // Check cache before computing
    if (lookup[n] != 0) {
        return lookup[n];
    }

    // Store and return
    lookup[n] = fib_opt(n - 1) + fib_opt(n - 2);
    return lookup[n];
}
// Initial call: fib_opt(50)
// lookup table ensures linearity.
